    #![allow(unused)]
    fn main() {
    #[cfg(target_arch = "x86_64")] {
    let bytes: *const u8;
    let len: usize;
    unsafe {
        core::arch::asm!(
            "jmp 3f", "2: .ascii \"Hello World!\"",
            "3: lea {bytes}, [2b+rip]",
