🔬This is a nightly-only experimental API. (hash_set_entry #60896)

Expand description

A view into an occupied entry in a HashSet. It is part of the Entry enum.

§Examples

    #![feature(hash_set_entry)]

    use std::collections::hash_set::{Entry, HashSet};

    let mut set = HashSet::new();
    set.extend(["a", "b", "c"]);

    let _entry_o = set.entry("a").insert();
    assert_eq!(set.len(), 3);

    // Existing key
    match set.entry("a") {
        Entry::Vacant(_) => unreachable!(),
        Entry::Occupied(view) => {
            assert_eq!(view.get(), &"a");
        }
    }

    assert_eq!(set.len(), 3);

    // Existing key (take)
    match set.entry("c") {
        Entry::Vacant(_) => unreachable!(),
        Entry::Occupied(view) => {
            assert_eq!(view.remove(), "c");
        }
    }
    assert_eq!(set.get(&"c"), None);
    assert_eq!(set.len(), 2);

