    assert_eq!(b.len(), 0);

    assert_eq!(a[&1], "a");
    assert_eq!(a[&2], "b");
    assert_eq!(a[&3], "d"); // Note: "c" has been overwritten.
    assert_eq!(a[&4], "e");
