    use std::fmt;

    struct Foo(i32);

    impl fmt::Display for Foo {
        fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
            if formatter.sign_plus() {
                write!(formatter,
                       "Foo({}{})",
                       if self.0 < 0 { '-' } else { '+' },
